# New hypothesis: A cell becomes 2 if it can "see" two DIFFERENT anchor points 
# that are NOT ALREADY connected by anchors themselves

def analyze_connectivity(grid, bg_color, struct_color, target_bg_cells=True):
    """Find connected components of structure, then determine which background cells see multiple distinct components"""
    R, C = len(grid), len(grid[0])

    # Find all structure positions
    structs = [(r,c) for r in range(R) for c in range(C) if grid[r][c] == struct_color]

    # Build adjacency graph for structures (connect if orthogonally adjacent OR separated by ONLY background on straight line)
    from collections import defaultdict, deque

    adj = defaultdict(set)
    for s1 in structs:
        r1, c1 = s1
        # Look in all 4 directions
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            r, c = r1+dr, c1+dc
            while 0<=r<R and 0<=c<C:
                val = grid[r][c]
                if val == struct_color:
                    adj[s1].add((r,c))
                    break  # Found another structure
                elif val != bg_color:
                    break  # Blocked by non-bg-non-struct
                r += dr
                c += dc

    # Build connected components of structures
    visited = set()
    components = []
    for s in structs:
        if s not in visited:
            comp = set()
            queue = deque([s])
            visited.add(s)
            while queue:
                curr = queue.popleft()
                comp.add(curr)
                for nb in adj[curr]:
                    if nb not in visited:
                        visited.add(nb)
                        queue.append(nb)
            components.append(comp)

    print(f"Found {len(components)} structure components")

    # Now find background cells that "see" at least 2 DIFFERENT components
    if target_bg_cells:
        seen_comp_ids = {}
        for r in range(R):
            for c in range(C):
                if grid[r][c] == bg_color:
                    comps_seen = []
                    # Check horizontal visibility to each component
                    found_first = False
                    for k in range(C):
                        if grid[r][k] == struct_color:
                            comps_seen.append(k)
                    for i, kc in enumerate(comps_seen):
                        # Which component does this belong to?
                        comp_id = None
                        for cid, comp in enumerate(components):
                            if (r,kc) in comp:
                                comp_id = cid
                                break
                        if comp_id not in comps_seen:
                            comps_seen.append(comp_id)

                    # Check vertical visibility
                    comps_vertical = []
                    found_first_v = False
                    for kr in range(R):
                        if grid[kr][c] == struct_color:
                            comps_vertical.append(kr)
                    for i, kv in enumerate(comps_vertical):
                        comp_id = None
                        for cid, comp in enumerate(components):
                            if (kv,c) in comp:
                                comp_id = cid
                                break
                        if comp_id not in comps_seen:
                            comps_seen.append(comp_id)

                    if len(set(comps_seen)) >= 2:
                        seen_comp_ids[(r,c)] = True

        return seen_comp_ids

    return None

