def predict_opposite_view(grid):
    R, C = len(grid), len(grid[0])
    bg_color = 3
    struct_color = 8

    # Find connected components
    structs = [(r,c) for r in range(R) for c in range(C) if grid[r][c] == struct_color]

    visited = set()
    components = []
    from collections import deque

    for start in structs:
        if start not in visited:
            comp = set([start])
            queue = deque([start])
            while queue:
                curr = queue.popleft()
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = curr[0]+dr, curr[1]+dc
                    if 0<=nr<R and 0<=nc<C and grid[nr][nc]==struct_color and (nr,nc) not in visited:
                        comp.add((nr,nc))
                        queue.append((nr,nc))
                        visited.add((nr,nc))
            components.append(comp)

    result = set()  # cells that change

    # For each bg cell, check if it sees two DIFFERENT components in opposite directions
    for r in range(R):
        for c in range(C):
            if grid[r][c] != bg_color:
                continue

            # Horizontal check
            seen_left = None
            seen_right = None
            for cc in range(c-1, -1, -1):
                if grid[r][cc] == struct_color:
                    # Find which component this belongs to
                    for cid, comp in enumerate(components):
                        if (r,cc) in comp:
                            seen_left = cid
                            break
                    break
            for cc in range(c+1, C):
                if grid[r][cc] == struct_color:
                    for cid, comp in enumerate(components):
                        if (r,cc) in comp:
                            seen_right = cid
                            break
                    break

            if seen_left is not None and seen_right is not None and seen_left != seen_right:
                result.add((r,c))

            # Vertical check
            seen_up = None
            seen_down = None
            for rr in range(r-1, -1, -1):
                if grid[rr][c] == struct_color:
                    for cid, comp in enumerate(components):
                        if (rr,c) in comp:
                            seen_up = cid
                            break
                    break
            for rr in range(r+1, R):
                if grid[rr][c] == struct_color:
                    for cid, comp in enumerate(components):
                        if (rr,c) in comp:
                            seen_down = cid
                            break
                    break

            if seen_up is not None and seen_down is not None and seen_up != seen_down:
                result.add((r,c))

    return result

