def predict_between_adjacent_anchors(grid):
    R, C = len(grid), len(grid[0])
    bg_color = 3
    struct_color = 8

    # First find all anchors in each row/col
    row_anchors = {}
    for r in range(R):
        row_anchors[r] = sorted([c for c in range(C) if grid[r][c] == struct_color])

    col_anchors = {}
    for c in range(C):
        col_anchors[c] = sorted([r for r in range(R) if grid[r][c] == struct_color])

    result = set()

    # For each row, fill between consecutive anchors
    for r in range(R):
        anchors = row_anchors.get(r, [])
        for i in range(len(anchors)-1):
            c1, c2 = anchors[i], anchors[i+1]
            # Fill all bg cells between c1 and c2
            for c in range(c1+1, c2):
                if grid[r][c] == bg_color:
                    result.add((r,c))

    # For each col, fill between consecutive anchors
    for c in range(C):
        anchors = col_anchors.get(c, [])
        for i in range(len(anchors)-1):
            r1, r2 = anchors[i], anchors[i+1]
            for r in range(r1+1, r2):
                if grid[r][c] == bg_color:
                    result.add((r,c))

    return result

